        // Fresh contract is unpaused. The reference must report false;
        // the mutant always reports true. Fuzz over whether the caller paused first.
        if (pausedBefore) {
            // cannot pause without admin role in a fresh deploy, so stay unpaused
        }
        bool reported = c.paused();
        assertTrue(reported == false);
    }
